import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
from PIL import Image
r=Robot();now=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:14],float);q=np.array([0.,1,0,0]);start=now[:3];goal=np.array([-.016,.145,-.003]);n=int(np.ceil(np.linalg.norm(goal-start)/.003));A=np.array([np.r_[start+(goal-start)*i/n,q] for i in range(1,n+1)]+[np.r_[goal,q] for _ in range(20)],np.float32);res=r.submit('ee_pose',A,dt=.05,video='frames',video_fps=20,cameras=['scene_cam'],note='test near handle-stop ink depth');print('z range',res.proprio[:,9].min(),res.proprio[:,9].max(),'end',res.proprio[-1,7:10]);
for c,a in res.last.items():Image.fromarray(a).save('/app/output/stopdip_'+c+'.png')
for c,a in res.frames.items():Image.fromarray(a[-1]).save('/app/output/stopdip_'+c+'_last.png')
